cd /tmp/sv-70167f444da749d3bd6241b2fa0f8bb3/advanced-multi-complexity && python3 << 'EOF'
import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def extract(data):
    result = {}
    for proj in data.get('projects', []):
        pname = proj['path'].split('/')[-1]
        for fw in proj.get('frameworks', []):
            tfm = fw['framework']
            for pkg in fw.get('topLevelPackages', []):
                key = (pname, tfm, pkg['id'])
                result[key] = (pkg['requestedVersion'], pkg['resolvedVersion'])
    return result

b = extract(baseline)
a = extract(after)

changes = []
unchanged = []

all_keys = sorted(set(b.keys()) | set(a.keys()))
for k in all_keys:
    proj, tfm, pkg = k
    if k in b and k in a:
        breq, bres = b[k]
        areq, ares = a[k]
        if bres != ares:
            changes.append(f"| {proj} | {tfm} | {pkg} | {bres} | {ares} | Version aligned to highest |")
        elif breq != areq:
            changes.append(f"| {proj} | {tfm} | {pkg} | {bres} | {ares} | Requested version changed (resolved same) |")
        else:
            unchanged.append(f"| {proj} | {tfm} | {pkg} | {bres} |")
    elif k in b and k not in a:
        breq, bres = b[k]
        changes.append(f"| {proj} | {tfm} | {pkg} | {bres} | REMOVED | Package removed |")
    else:
        areq, ares = a[k]
        changes.append(f"| {proj} | {tfm} | {pkg} | - | {ares} | Package added |")

print("=== CHANGES ===")
if changes:
    for c in changes: print(c)
else:
    print("None")

print("\n=== UNCHANGED ===")
for u in unchanged: print(u)
